import{_ as a,c as i,o as t,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Behavior Analysis","description":"","frontmatter":{"title":"Behavior Analysis"},"headers":[],"relativePath":"general/behavior-analysis.md","filePath":"general/behavior-analysis.md","lastUpdated":null}'),r={name:"general/behavior-analysis.md"};function l(n,e,s,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="behavior-analysis" tabindex="-1">Behavior Analysis <a class="header-anchor" href="#behavior-analysis" aria-label="Permalink to &quot;Behavior Analysis&quot;">​</a></h1><h2 id="action-or-behavior-analysis-template" tabindex="-1">Action or Behavior Analysis Template <a class="header-anchor" href="#action-or-behavior-analysis-template" aria-label="Permalink to &quot;Action or Behavior Analysis Template&quot;">​</a></h2><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>To build upon the latest doctrine <a href="/general/pmesii-pt.html">TM 3-53.11 Influence Process Activity: Target Audience Analysis</a> Chapter 2 by providing a more in-depth analysis of a specific behavior in a particular area. This template aims to produce a shared understanding of the behavior and relevant actors, locations, obstacles, symbols, etc., associated with it.</p><p>The capability required to conduct behaviors and the opportunity to perform the behavior and intermediate behaviors may vary significantly depending on the area, from country to country down to street by street.</p><p>This is NOT a MISO-only analysis, as it may include and benefit all other units operating in the area. The MISO desired behavior may differ from the behavior identified and analyzed in this process; it may consist of several analyzed behaviors that are intermediate steps toward a broader MISO desired behavior.</p><p>This template is also available on SIPR with the same name.</p><h3 id="how-to-use-template" tabindex="-1">How To Use Template <a class="header-anchor" href="#how-to-use-template" aria-label="Permalink to &quot;How To Use Template&quot;">​</a></h3><ol><li>Select the &quot;Edit source&quot; option above.</li><li>Copy all the content below, including the headers and formatting syntax.</li><li>Replace all placeholders enclosed in double square brackets (e.g., <code>[BEHAVIOR]</code>, <code>[COUNTRY]</code>) with your specific information.</li><li>Search for the term &quot;DESIRED_BEHAVIOR in COUNTRY_HERE&quot;. <ul><li>If the page does not exist, select &quot;Create Page&quot; at the top of the results.</li></ul></li><li>Paste the content you copied in Step 2 into the new page.</li><li>Remove this instruction section above the &quot;snip line here&quot;.</li><li>Save the new page.</li><li>Use the normal &quot;Edit&quot; option to fill in the details.</li></ol><hr><h2 id="template-starts-here" tabindex="-1">Template Starts Here <a class="header-anchor" href="#template-starts-here" aria-label="Permalink to &quot;Template Starts Here&quot;">​</a></h2><p><strong>Action or Behavior</strong>: [BEHAVIOR] in [COUNTRY]</p><h3 id="behavior-breakdown-and-analysis" tabindex="-1">Behavior Breakdown and Analysis <a class="header-anchor" href="#behavior-breakdown-and-analysis" aria-label="Permalink to &quot;Behavior Breakdown and Analysis&quot;">​</a></h3><h3 id="behavior-timeline" tabindex="-1">Behavior Timeline <a class="header-anchor" href="#behavior-timeline" aria-label="Permalink to &quot;Behavior Timeline&quot;">​</a></h3><ul><li><p><strong>Instances of the Behavior</strong></p><ul><li>Document specific instances when the behavior has occurred.</li></ul></li><li><p><strong>Where does the behavior occur?</strong></p><ul><li>Specify geographic locations (regions, cities, specific sites).</li></ul></li><li><p><strong>When does the behavior occur?</strong></p><ul><li>Include dates, times, and frequency.</li></ul></li><li><p><strong>Duration of the Behavior</strong></p><ul><li>Indicate how long each instance lasts.</li></ul></li></ul><h3 id="supporting-behaviors-required" tabindex="-1">Supporting Behaviors Required <a class="header-anchor" href="#supporting-behaviors-required" aria-label="Permalink to &quot;Supporting Behaviors Required&quot;">​</a></h3><ul><li><p><strong>Identify all supporting behaviors necessary for the main behavior to occur.</strong></p><ul><li>List and describe each supporting behavior in sequence.</li></ul></li><li><p><strong>Timeline of Supporting Behaviors</strong></p><ul><li>Create a chronological timeline showing when supporting behaviors occur relative to the main behavior.</li></ul></li></ul><h3 id="obstacles-and-challenges-encountered" tabindex="-1">Obstacles and Challenges Encountered <a class="header-anchor" href="#obstacles-and-challenges-encountered" aria-label="Permalink to &quot;Obstacles and Challenges Encountered&quot;">​</a></h3><ul><li><strong>Document obstacles or challenges that have been encountered during supporting behaviors.</strong><ul><li>Physical barriers</li><li>Legal restrictions</li><li>Social opposition</li><li>Resource limitations</li></ul></li></ul><h3 id="associated-symbols-and-signals" tabindex="-1">Associated Symbols and Signals <a class="header-anchor" href="#associated-symbols-and-signals" aria-label="Permalink to &quot;Associated Symbols and Signals&quot;">​</a></h3><ul><li><strong>Identify symbols or signals that have been associated with the supporting behaviors.</strong><ul><li>Cultural symbols</li><li>Gestures</li><li>Codes or signals used for coordination</li></ul></li></ul><h3 id="required-capabilities-physical-cognitive-social-economic" tabindex="-1">Required Capabilities (Physical, Cognitive, Social, Economic) <a class="header-anchor" href="#required-capabilities-physical-cognitive-social-economic" aria-label="Permalink to &quot;Required Capabilities (Physical, Cognitive, Social, Economic)&quot;">​</a></h3><ul><li><strong>Detail the capabilities required to perform the supporting behaviors.</strong><ul><li>Physical capabilities (skills, tools)</li><li>Cognitive capabilities (knowledge, planning)</li><li>Social capabilities (networks, group coordination)</li><li>Economic capabilities (funding, resources)</li></ul></li></ul><h3 id="social-norms-and-pressures" tabindex="-1">Social Norms and Pressures <a class="header-anchor" href="#social-norms-and-pressures" aria-label="Permalink to &quot;Social Norms and Pressures&quot;">​</a></h3><ul><li><strong>Describe the social norms or pressures connected with the supporting behaviors.</strong><ul><li>Cultural expectations</li><li>Peer pressure</li><li>Traditional practices</li></ul></li></ul><h3 id="motivations-and-drivers" tabindex="-1">Motivations and Drivers <a class="header-anchor" href="#motivations-and-drivers" aria-label="Permalink to &quot;Motivations and Drivers&quot;">​</a></h3><ul><li><strong>What motivates individuals to engage in the behavior?</strong><ul><li>Document known motivations based on data (e.g., personal benefits, ideological beliefs).</li></ul></li></ul><h3 id="consequences-and-outcomes" tabindex="-1">Consequences and Outcomes <a class="header-anchor" href="#consequences-and-outcomes" aria-label="Permalink to &quot;Consequences and Outcomes&quot;">​</a></h3><ul><li><strong>What have been the consequences of the behavior for the actors and the community?</strong><ul><li>Positive outcomes</li><li>Negative repercussions</li></ul></li></ul><h3 id="environmental-and-situational-factors" tabindex="-1">Environmental and Situational Factors <a class="header-anchor" href="#environmental-and-situational-factors" aria-label="Permalink to &quot;Environmental and Situational Factors&quot;">​</a></h3><ul><li><strong>Identify environmental factors that have influenced the behavior.</strong><ul><li>Political climate</li><li>Economic conditions</li><li>Technological availability</li></ul></li></ul><h3 id="strategies-that-have-impacted-the-behavior" tabindex="-1">Strategies That Have Impacted the Behavior <a class="header-anchor" href="#strategies-that-have-impacted-the-behavior" aria-label="Permalink to &quot;Strategies That Have Impacted the Behavior&quot;">​</a></h3><ul><li><strong>Document strategies that have previously impacted the behavior.</strong><ul><li>Include example strategies, whether they increased or decreased the behavior.</li><li>Describe how these strategies affected the behavior.</li></ul></li></ul><h3 id="target-audience-refinement-based-on-supporting-behavior" tabindex="-1">Target Audience Refinement Based on Supporting Behavior <a class="header-anchor" href="#target-audience-refinement-based-on-supporting-behavior" aria-label="Permalink to &quot;Target Audience Refinement Based on Supporting Behavior&quot;">​</a></h3><h4 id="potential-primary-target-audiences" tabindex="-1">Potential Primary Target Audiences <a class="header-anchor" href="#potential-primary-target-audiences" aria-label="Permalink to &quot;Potential Primary Target Audiences&quot;">​</a></h4><ol><li>[Primary TA 1]</li><li>[Primary TA 2]</li></ol><h4 id="potential-secondary-target-audiences" tabindex="-1">Potential Secondary Target Audiences <a class="header-anchor" href="#potential-secondary-target-audiences" aria-label="Permalink to &quot;Potential Secondary Target Audiences&quot;">​</a></h4><ol><li>[Secondary TA 1]</li><li>[Secondary TA 2]</li></ol><h3 id="engaging-actors" tabindex="-1">Engaging Actors <a class="header-anchor" href="#engaging-actors" aria-label="Permalink to &quot;Engaging Actors&quot;">​</a></h3><ul><li><strong>Who is currently engaging (or has engaged) in the behavior or supporting behaviors?</strong><ul><li>Identify specific groups or demographics.</li></ul></li></ul><h3 id="beneficiaries" tabindex="-1">Beneficiaries <a class="header-anchor" href="#beneficiaries" aria-label="Permalink to &quot;Beneficiaries&quot;">​</a></h3><ul><li><strong>Who has benefited from the behavior or supporting behaviors or actions?</strong><ul><li>List direct and indirect beneficiaries.</li></ul></li></ul><h3 id="harmed-parties" tabindex="-1">Harmed Parties <a class="header-anchor" href="#harmed-parties" aria-label="Permalink to &quot;Harmed Parties&quot;">​</a></h3><ul><li><strong>Who has been hurt by or perceives themselves to be harmed by the behavior or supporting behaviors?</strong><ul><li>Identify opposing groups or unintended victims.</li></ul></li></ul><h3 id="influencers-and-stakeholders" tabindex="-1">Influencers and Stakeholders <a class="header-anchor" href="#influencers-and-stakeholders" aria-label="Permalink to &quot;Influencers and Stakeholders&quot;">​</a></h3><ul><li><strong>Who has directly or indirectly influenced the supporting behavior of the primary actors?</strong><ul><li>Leaders</li><li>Organizations</li><li>Media</li></ul></li></ul><h3 id="enablers-and-supporters" tabindex="-1">Enablers and Supporters <a class="header-anchor" href="#enablers-and-supporters" aria-label="Permalink to &quot;Enablers and Supporters&quot;">​</a></h3><ul><li><strong>Who has enabled the behavior or supporting behaviors?</strong><ul><li>Sponsors</li><li>Suppliers</li><li>Facilitators</li></ul></li></ul><h3 id="opposers-and-detractors" tabindex="-1">Opposers and Detractors <a class="header-anchor" href="#opposers-and-detractors" aria-label="Permalink to &quot;Opposers and Detractors&quot;">​</a></h3><ul><li><strong>Who has opposed the behavior or supporting behaviors?</strong><ul><li>Competitors</li><li>Regulatory bodies</li><li>Community groups</li></ul></li></ul><h3 id="additional-notes" tabindex="-1">Additional Notes <a class="header-anchor" href="#additional-notes" aria-label="Permalink to &quot;Additional Notes&quot;">​</a></h3><ul><li><p><strong>Cultural Considerations</strong></p><ul><li>Note any relevant cultural factors.</li></ul></li><li><p><strong>Legal and Ethical Implications</strong></p><ul><li>Highlight any legal or ethical issues.</li></ul></li></ul>',52)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
